70	void MetalinkEntry::setProtocolPriority(const std::string& protocol,
71	                                        int priorityToAdd)
72	{
73	  for (auto& res : resources) {
74	    if (protocol == MetalinkResource::getTypeString(res->type)) {
75	      res->priority += priorityToAdd;
76	    }
77	  }
78	}
