90	void MetalinkEntry::reorderResourcesByPriority()
91	{
92	  std::shuffle(std::begin(resources), std::end(resources),
93	               *SimpleRandomizer::getInstance());
94	  std::sort(std::begin(resources), std::end(resources),
95	            PriorityHigher<std::unique_ptr<MetalinkResource>>{});
96	}
