112	#ifdef ENABLE_SSL
113	    case MetalinkResource::TYPE_HTTPS:
114	#endif // ENABLE_SSL
115	#ifdef ENABLE_BITTORRENT
116	    case MetalinkResource::TYPE_BITTORRENT:
117	#endif // ENABLE_BITTORRENT
