126	void MetalinkEntry::dropUnsupportedResource()
127	{
128	  resources.erase(
129	      std::remove_if(std::begin(resources), std::end(resources),
130	                     [](const std::unique_ptr<MetalinkResource>& res) {
131	                       switch (res->type) {
132	                       case MetalinkResource::TYPE_FTP:
133	                       case MetalinkResource::TYPE_HTTP:
134	#ifdef ENABLE_SSL
135	                       case MetalinkResource::TYPE_HTTPS:
136	#endif // ENABLE_SSL
137	#ifdef ENABLE_BITTORRENT
138	                       case MetalinkResource::TYPE_BITTORRENT:
139	#endif // ENABLE_BITTORRENT
140	                         return false;
141	                       default:
142	                         return true;
143	                       }
144	                     }),
145	      std::end(resources));
