114	void Metalink2RequestGroup::generate(
115	    std::vector<std::shared_ptr<RequestGroup>>& groups,
116	    const std::string& metalinkFile, const std::shared_ptr<Option>& option,
117	    const std::string& baseUri)
118	{
119	  std::vector<std::shared_ptr<RequestGroup>> tempgroups;
120	  createRequestGroup(
121	      tempgroups, metalink::parseAndQuery(metalinkFile, option.get(), baseUri),
122	      option);
