130	    mi = std::make_shared<MetadataInfo>(GroupId::create(), metalinkFile);
131	  }
132	  setMetadataInfo(std::begin(tempgroups), std::end(tempgroups), mi);
133	  groups.insert(std::end(groups), std::begin(tempgroups), std::end(tempgroups));
134	}
135	
136	void Metalink2RequestGroup::generate(
137	    std::vector<std::shared_ptr<RequestGroup>>& groups,
138	    const std::shared_ptr<BinaryStream>& binaryStream,
139	    const std::shared_ptr<Option>& option, const std::string& baseUri)
140	{
141	  std::vector<std::shared_ptr<RequestGroup>> tempgroups;
142	  createRequestGroup(
143	      tempgroups,
144	      metalink::parseAndQuery(binaryStream.get(), option.get(), baseUri),
145	      option);
146	  auto mi = std::make_shared<MetadataInfo>();
147	  setMetadataInfo(std::begin(tempgroups), std::end(tempgroups), mi);
148	  groups.insert(std::end(groups), std::begin(tempgroups), std::end(tempgroups));
149	}
150	
151	void Metalink2RequestGroup::createRequestGroup(
152	    std::vector<std::shared_ptr<RequestGroup>>& groups,
153	    std::vector<std::unique_ptr<MetalinkEntry>> entries,
154	    const std::shared_ptr<Option>& optionTemplate)
155	{
156	  if (entries.empty()) {
157	    A2_LOG_NOTICE(EX_NO_RESULT_WITH_YOUR_PREFS);
158	    return;
159	  }
160	  std::vector<std::string> locations;
161	  if (optionTemplate->defined(PREF_METALINK_LOCATION)) {
162	    auto& loc = optionTemplate->get(PREF_METALINK_LOCATION);
163	    util::split(std::begin(loc), std::end(loc), std::back_inserter(locations),
164	                ',', true);
165	    for (auto& s : locations) {
166	      util::lowercase(s);
167	    }
168	  }
169	  std::string preferredProtocol;
170	  if (optionTemplate->get(PREF_METALINK_PREFERRED_PROTOCOL) != V_NONE) {
171	    preferredProtocol = optionTemplate->get(PREF_METALINK_PREFERRED_PROTOCOL);
172	  }
173	  for (auto& entry : entries) {
174	    entry->dropUnsupportedResource();
175	    if (entry->resources.empty() && entry->metaurls.empty()) {
176	      continue;
177	    }
178	    entry->setLocationPriority(locations,
179	                               -MetalinkResource::getLowestPriority());
180	    if (!preferredProtocol.empty()) {
181	      entry->setProtocolPriority(preferredProtocol,
182	                                 -MetalinkResource::getLowestPriority());
183	    }
184	  }
185	  auto sgl = util::parseIntSegments(optionTemplate->get(PREF_SELECT_FILE));
186	  sgl.normalize();
187	  if (sgl.hasNext()) {
188	    size_t inspoint = 0;
189	    for (size_t i = 0, len = entries.size(); i < len && sgl.hasNext(); ++i) {
190	      size_t j = sgl.peek() - 1;
191	      if (i == j) {
192	        if (inspoint != i) {
193	          entries[inspoint] = std::move(entries[i]);
194	        }
195	        ++inspoint;
196	        sgl.next();
197	      }
198	    }
199	    entries.resize(inspoint);
200	  }
201	  std::for_each(std::begin(entries), std::end(entries),
202	                std::mem_fn(&MetalinkEntry::reorderMetaurlsByPriority));
203	  auto entryGroups = metalink::groupEntryByMetaurlName(entries);
204	  for (auto& entryGroup : entryGroups) {
205	    auto& metaurl = entryGroup.first;
206	    auto& mes = entryGroup.second;
207	    A2_LOG_INFO(fmt("Processing metaurl group metaurl=%s", metaurl.c_str()));
208	#ifdef ENABLE_BITTORRENT
209	    std::shared_ptr<RequestGroup> torrentRg;
210	    if (!metaurl.empty()) {
211	      std::vector<std::string> uris;
212	      uris.push_back(metaurl);
213	      {
214	        std::vector<std::shared_ptr<RequestGroup>> result;
215	        createRequestGroupForUri(result, optionTemplate, uris,
216	                                 /* ignoreForceSequential = */ true,
217	                                 /* ignoreLocalPath = */ true);
218	        if (!result.empty()) {
219	          torrentRg = result[0];
220	        }
221	      }
222	      if (torrentRg) {
223	        torrentRg->setNumConcurrentCommand(1);
224	        torrentRg->clearPreDownloadHandler();
225	        torrentRg->clearPostDownloadHandler();
226	        // remove "metalink" from Accept Type list to avoid loop in
227	        // transparent metalink
228	        torrentRg->getDownloadContext()->setAcceptMetalink(false);
229	        // make it in-memory download
230	        torrentRg->addPreDownloadHandler(
231	            download_handlers::getMemoryPreDownloadHandler());
232	        torrentRg->markInMemoryDownload();
233	        groups.push_back(torrentRg);
234	      }
235	    }
236	#endif // ENABLE_BITTORRENT
237	    auto option = util::copy(optionTemplate);
238	    auto rg = std::make_shared<RequestGroup>(GroupId::create(), option);
239	    std::shared_ptr<DownloadContext> dctx;
240	    int numSplit = option->getAsInt(PREF_SPLIT);
241	    int maxConn = option->getAsInt(PREF_MAX_CONNECTION_PER_SERVER);
242	    if (mes.size() == 1) {
243	      auto entry = mes[0];
244	      A2_LOG_INFO(fmt(MSG_METALINK_QUEUEING, entry->getPath().c_str()));
245	      entry->reorderResourcesByPriority();
246	      for (auto& mr : entry->resources) {
247	        A2_LOG_DEBUG(fmt("priority=%d url=%s", mr->priority, mr->url.c_str()));
248	      }
249	      std::vector<std::string> uris;
250	      std::for_each(std::begin(entry->resources), std::end(entry->resources),
251	                    AccumulateNonP2PUri(uris));
252	      // If piece hash is specified in the metalink,
253	      // make segment size equal to piece hash size.
254	      int32_t pieceLength;
255	      if (!entry->chunkChecksum) {
256	        pieceLength = option->getAsInt(PREF_PIECE_LENGTH);
257	      }
258	      else {
259	        pieceLength = entry->chunkChecksum->getPieceLength();
260	      }
261	      dctx = std::make_shared<DownloadContext>(
262	          pieceLength, entry->getLength(),
263	          util::applyDir(option->get(PREF_DIR), entry->file->getPath()));
264	      dctx->getFirstFileEntry()->setUris(uris);
265	      dctx->getFirstFileEntry()->setMaxConnectionPerServer(maxConn);
266	      dctx->getFirstFileEntry()->setSuffixPath(entry->file->getPath());
267	      if (!entry->metaurls.empty()) {
268	        dctx->getFirstFileEntry()->setOriginalName(entry->metaurls[0]->name);
269	      }
270	
271	      if (option->getAsBool(PREF_METALINK_ENABLE_UNIQUE_PROTOCOL)) {
272	        dctx->getFirstFileEntry()->setUniqueProtocol(true);
273	      }
274	      if (entry->checksum) {
275	        dctx->setDigest(entry->checksum->getHashType(),
276	                        entry->checksum->getDigest());
277	      }
278	      if (entry->chunkChecksum) {
279	        dctx->setPieceHashes(entry->chunkChecksum->getHashType(),
280	                             std::begin(entry->chunkChecksum->getPieceHashes()),
281	                             std::end(entry->chunkChecksum->getPieceHashes()));
282	      }
283	      dctx->setSignature(entry->popSignature());
284	      rg->setNumConcurrentCommand(
285	          entry->maxConnections < 0
286	              ? numSplit
287	              : std::min(numSplit, entry->maxConnections));
288	    }
289	    else {
290	      dctx = std::make_shared<DownloadContext>();
291	      // piece length is overridden by the one in torrent file.
292	      dctx->setPieceLength(option->getAsInt(PREF_PIECE_LENGTH));
293	      std::vector<std::shared_ptr<FileEntry>> fileEntries;
294	      int64_t offset = 0;
295	      for (auto entry : mes) {
296	        A2_LOG_INFO(fmt("Metalink: Queueing %s for download as a member.",
297	                        entry->getPath().c_str()));
298	        A2_LOG_DEBUG(
299	            fmt("originalName = %s", entry->metaurls[0]->name.c_str()));
300	        entry->reorderResourcesByPriority();
301	        std::vector<std::string> uris;
302	        std::for_each(std::begin(entry->resources), std::end(entry->resources),
303	                      AccumulateNonP2PUri(uris));
304	        auto fe = std::make_shared<FileEntry>(
305	            util::applyDir(option->get(PREF_DIR), entry->file->getPath()),
306	            entry->file->getLength(), offset, uris);
307	        fe->setMaxConnectionPerServer(maxConn);
308	        if (option->getAsBool(PREF_METALINK_ENABLE_UNIQUE_PROTOCOL)) {
309	          fe->setUniqueProtocol(true);
310	        }
311	        fe->setOriginalName(entry->metaurls[0]->name);
312	        fe->setSuffixPath(entry->file->getPath());
313	        fileEntries.push_back(fe);
314	        if (offset >
315	            std::numeric_limits<int64_t>::max() - entry->file->getLength()) {
316	          throw DOWNLOAD_FAILURE_EXCEPTION(fmt(EX_TOO_LARGE_FILE, offset));
317	        }
318	        offset += entry->file->getLength();
319	      }
320	      dctx->setFileEntries(std::begin(fileEntries), std::end(fileEntries));
321	      rg->setNumConcurrentCommand(numSplit);
322	    }
323	    rg->setDownloadContext(dctx);
324	
325	    if (option->getAsBool(PREF_ENABLE_RPC)) {
326	      rg->setPauseRequested(option->getAsBool(PREF_PAUSE));
327	    }
328	
329	    removeOneshotOption(option);
330	    // remove "metalink" from Accept Type list to avoid loop in
331	    // transparent metalink
332	    dctx->setAcceptMetalink(false);
333	#ifdef ENABLE_BITTORRENT
334	    // Inject dependency between rg and torrentRg here if
335	    // torrentRg is true
336	    if (torrentRg) {
337	      auto dep = std::make_shared<BtDependency>(rg.get(), torrentRg);
338	      rg->dependsOn(dep);
339	      torrentRg->belongsTo(rg->getGID());
340	      // metadata download may take very long time. If URIs are
341	      // available, give up metadata download in at most 30 seconds.
342	      const time_t btStopTimeout = 30;
343	      time_t currentBtStopTimeout =
344	          torrentRg->getOption()->getAsInt(PREF_BT_STOP_TIMEOUT);
345	      if (currentBtStopTimeout == 0 || currentBtStopTimeout > btStopTimeout) {
346	        bool allHaveUri = true;
347	        for (auto& fe : dctx->getFileEntries()) {
348	          if (fe->getRemainingUris().empty()) {
349	            allHaveUri = false;
350	            break;
351	          }
352	        }
353	        if (allHaveUri) {
354	          torrentRg->getOption()->put(PREF_BT_STOP_TIMEOUT,
355	                                      util::itos(btStopTimeout));
356	        }
357	      }
358	    }
359	#endif // ENABLE_BITTORRENT
360	    groups.push_back(rg);
361	  }
362	}
363	
364	} // namespace aria2
365

