39	MetalinkHttpEntry::MetalinkHttpEntry() : pri(999999), pref(false) {}
40	
41	MetalinkHttpEntry::~MetalinkHttpEntry() = default;
42	
43	void MetalinkHttpEntry::swap(MetalinkHttpEntry& other)
44	{
45	  using std::swap;
46	  if (this != &other) {
47	    swap(uri, other.uri);
48	    swap(pri, other.pri);
49	    swap(pref, other.pref);
50	    swap(geo, other.geo);
51	  }
52	}
53	
54	bool MetalinkHttpEntry::operator<(const MetalinkHttpEntry& rhs) const
55	{
56	  if (pref ^ rhs.pref) {
57	    return pref;
58	  }
59	  else {
60	    return pri < rhs.pri;
61	  }
62	}
63	
64	void swap(MetalinkHttpEntry& a, MetalinkHttpEntry& b) { a.swap(b); }
65	
