65	const std::string& getBaseUri(RequestGroup* requestGroup)
66	{
67	  auto& dctx = requestGroup->getDownloadContext();
68	  if (dctx->getFileEntries().empty()) {
69	    return A2STR::NIL;
70	  }
71	  else {
72	    // TODO Check download result for each URI
73	    auto& entry = dctx->getFirstFileEntry();
74	    auto& spentUris = entry->getSpentUris();
75	    if (spentUris.empty()) {
76	      auto& remainingUris = entry->getRemainingUris();
77	      if (remainingUris.empty()) {
78	        return A2STR::NIL;
79	      }
80	      else {
81	        return remainingUris.front();
82	      }
83	    }
84	    else {
85	      return spentUris.back();
86	    }
87	  }
88	}
