91	void MetalinkPostDownloadHandler::getNextRequestGroups(
92	    std::vector<std::shared_ptr<RequestGroup>>& groups,
93	    RequestGroup* requestGroup) const
94	{
95	  A2_LOG_DEBUG(fmt("Generating RequestGroups for Metalink file %s",
96	                   requestGroup->getFirstFilePath().c_str()));
97	  auto diskAdaptor = requestGroup->getPieceStorage()->getDiskAdaptor();
98	  try {
99	    diskAdaptor->openExistingFile();
100	    // requestOption.put(PREF_DIR,
101	    // requestGroup->getDownloadContext()->getDir());
102	    const std::string& baseUri = getBaseUri(requestGroup);
103	    std::vector<std::shared_ptr<RequestGroup>> newRgs;
104	    Metalink2RequestGroup().generate(newRgs, diskAdaptor,
105	                                     requestGroup->getOption(), baseUri);
106	    requestGroup->followedBy(newRgs.begin(), newRgs.end());
107	    for (auto& rg : newRgs) {
108	      rg->following(requestGroup->getGID());
109	    }
110	    auto mi = createMetadataInfoFromFirstFileEntry(
111	        requestGroup->getGroupId(), requestGroup->getDownloadContext());
112	    if (mi) {
113	      setMetadataInfo(newRgs.begin(), newRgs.end(), mi);
114	    }
115	
116	    auto rgman = requestGroup->getRequestGroupMan();
117	
118	    if (rgman && rgman->getKeepRunning() &&
119	        requestGroup->getOption()->getAsBool(PREF_PAUSE_METADATA)) {
120	      for (auto& rg : newRgs) {
121	        rg->setPauseRequested(true);
122	      }
123	    }
124	
125	    groups.insert(groups.end(), newRgs.begin(), newRgs.end());
126	    diskAdaptor->closeFile();
127	  }
128	  catch (Exception& e) {
129	    diskAdaptor->closeFile();
130	    throw;
131	  }
132	}
